pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let root = std::fs::canonicalize("/app/sealwell").map_err(|_| 1)?;
    let archive = std::fs::canonicalize(a).map_err(|_| 1)?;
    if !archive.starts_with(&root) || !archive.is_file() { return Err(1); }
    let raw = std::fs::read(&archive).map_err(|_| 1)?;
    let mut recs = read_idx(b)?;
    recs.sort_by_key(|r| r.hdr);
    let mut conf: Option<Vec<u8>> = None;
    let mut events = Vec::new();
    let mut names = Vec::with_capacity(recs.len());
    for r in &recs {
        if r.body != r.hdr.checked_add(512).ok_or(1)? { return Err(1); }
        let blob = load(&raw, r.body, r.size)?;
        names.push(r.name.clone());
        if r.name.ends_with("sys.conf") && conf.is_none() { conf = Some(blob.clone()); }
