                let value = line.trim();
                if !value.is_empty() { events.push(value.to_string()); }
            }
        }
    }
    events.sort();
    events.dedup();
    let map = conf.as_deref().map(kv::pairs).unwrap_or_default();
    let source = archive.file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack {
